<div class="module-toolbar"><div><p class="module-intro"><?= kd_e($employee['employee_code']) ?> · <?= kd_e($employee['department_name']?:'Departman atanmamış') ?></p></div><div class="toolbar-actions"><a class="btn secondary action-link" href="index.php?page=employees">← Liste</a><a class="btn primary action-link" href="index.php?page=employees&action=edit&id=<?= (int)$employee['id'] ?>">Düzenle</a></div></div><div class="customer-detail-grid"><section class="panel customer-profile"><h2><?= kd_e($employee['first_name'].' '.$employee['last_name']) ?></h2><span class="customer-status <?= $employee['employment_status']==='active'?'is-active':'is-inactive' ?>"><?= kd_e($employee['employment_status']) ?></span><div class="profile-info"><div><small>E-posta</small><strong><?= kd_e($employee['email']?:'—') ?></strong></div><div><small>Telefon</small><strong><?= kd_e($employee['phone']?:'—') ?></strong></div><div><small>Pozisyon</small><strong><?= kd_e($employee['position']?:'—') ?></strong></div><div><small>İşe giriş</small><strong><?= kd_e($employee['hire_date']?:'—') ?></strong></div><div><small>Temel maaş</small><strong><?= number_format((float)$employee['base_salary'],2,',','.') ?> <?= kd_e($employee['currency']) ?></strong></div></div><a class="btn secondary action-link" href="index.php?page=employees&action=edit&id=<?= (int)$employee['id'] ?>">Personeli düzenle</a></section><section class="panel activity-panel"><h3>İzin talebi oluştur</h3><form method="post" class="activity-form"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="leave"><input type="hidden" name="employee_id" value="<?= (int)$employee['id'] ?>"><label>İzin türü<select name="leave_type"><option value="annual">Yıllık izin</option><option value="sick">Hastalık izni</option><option value="unpaid">Ücretsiz izin</option><option value="other">Diğer</option></select></label><label>Başlangıç<input type="date" name="start_date" required></label><label>Bitiş<input type="date" name="end_date" required></label><label>Neden<input name="reason" maxlength="255"></label><button class="btn primary">İzin talebi ekle</button></form><h3>İzin geçmişi</h3><?php foreach($leaves as $l): ?><article class="timeline-item"><strong><?= kd_e($l['leave_type']) ?> · <?= kd_e($l['status']) ?></strong><p><?= kd_e($l['start_date']) ?> — <?= kd_e($l['end_date']) ?> · <?= number_format((float)$l['day_count'],1,',','.') ?> gün</p><?php if($l['status']==='pending'): ?><div class="toolbar-actions"><?php foreach(['approved'=>'Onayla','rejected'=>'Reddet'] as $k=>$label): ?><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="leave_status"><input type="hidden" name="leave_id" value="<?= (int)$l['id'] ?>"><input type="hidden" name="employee_id" value="<?= (int)$employee['id'] ?>"><input type="hidden" name="status" value="<?= $k ?>"><button class="btn secondary"><?= $label ?></button></form><?php endforeach; ?></div><?php endif; ?></article><?php endforeach; ?></section></div>
<section class="panel customer-form-panel"><h3>Devam / puantaj kaydı</h3><form method="post"><input type="hidden" name="_csrf" value="<?= kd_e(kd_csrf_token()) ?>"><input type="hidden" name="form_action" value="attendance"><input type="hidden" name="employee_id" value="<?= (int)$employee['id'] ?>"><div class="customer-fields"><label>Tarih<input type="date" name="work_date" value="<?= date('Y-m-d') ?>"></label><label>Giriş<input type="datetime-local" name="check_in"></label><label>Çıkış<input type="datetime-local" name="check_out"></label><label>Not<input name="attendance_notes"></label></div><button class="btn secondary">Puantajı kaydet</button></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Tarih</th><th>Giriş</th><th>Çıkış</th><th>Not</th></tr></thead><tbody><?php foreach($attendance as $a): ?><tr><td><?= kd_e($a['work_date']) ?></td><td><?= kd_e($a['check_in']?:'—') ?></td><td><?= kd_e($a['check_out']?:'—') ?></td><td><?= kd_e($a['notes']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel customer-form-panel"><h3>Maaş / avans / prim ödemesi</h3><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="payment"><input type="hidden" name="employee_id" value="<?= (int)$employee['id'] ?>"><div class="customer-fields"><label>Ödeme türü<select name="payment_type"><option value="salary">Maaş</option><option value="advance">Avans</option><option value="bonus">Prim / bonus</option><option value="commission">Komisyon</option></select></label><label>Ödeme hesabı<select name="account_id"><?php foreach($paymentAccounts as $a): ?><option value="<?= (int)$a['id'] ?>"><?= kd_e($a['name']) ?></option><?php endforeach; ?></select></label><label>Dönem (YYYY-AA)<input name="pay_period" placeholder="2026-11" pattern="\d{4}-\d{2}" required></label><label>Tutar<input type="number" name="amount" min=".01" step=".01" value="<?= kd_e($employee['base_salary']) ?>" required></label><label>Ödeme tarihi<input type="date" name="payment_date" value="<?= date('Y-m-d') ?>"></label><label>Referans<input name="reference_no"></label><label class="field-wide">Not<input name="payment_notes"></label></div><button class="btn primary" <?= !$paymentAccounts?'disabled':'' ?>>Ödemeyi kaydet</button></form><h3>Ödeme geçmişi</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Dönem</th><th>Tür</th><th>Tarih</th><th>Hesap</th><th>Tutar</th></tr></thead><tbody><?php foreach($payments as $p): ?><tr><td><?= kd_e($p['pay_period']) ?></td><td><?= kd_e($p['payment_type']) ?></td><td><?= kd_e($p['payment_date']) ?></td><td><?= kd_e($p['account_name']) ?></td><td><?= number_format((float)$p['amount'],2,',','.') ?> <?= kd_e($p['currency']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
